  /* ---- Concept comparison laboratory ---- */
  var COMPARISONS = [
    { a: "Qualification", b: "Competence", simple: "A qualification is an award; a competence is an ability.", pro: "A qualification is a formal certification of achievement; a competence is the demonstrated ability to perform to a standard. A qualification usually certifies a set of competences.", diff: [["Nature", "Formal award / certificate", "Demonstrated ability"], ["Evidence", "Certificate on the register", "Performance to a standard"]], eduEg: "A diploma in nursing is a qualification.", lmEg: "Safely administering medication is a competence.", mistake: "Treating 'qualification' and 'competence' as identical.", question: "Can someone be competent without holding the relevant qualification?", model: "Yes. Competence is the ability to perform; a qualification is formal recognition of it. Recognition of prior learning exists precisely because competent people may lack the certificate." },
    { a: "Qualification", b: "Certificate", simple: "A qualification is the achievement; a certificate is the paper proving it.", pro: "A qualification is the recognised learning achievement at a level; a certificate is the physical or digital document evidencing that a qualification has been awarded.", diff: [["Meaning", "The achievement and its level", "The document of proof"]], eduEg: "Level-six diploma (qualification).", lmEg: "The printed diploma certificate.", mistake: "Assuming a certificate alone proves a level without register data.", question: "Why is a certificate not enough for a recognition decision?", model: "Because the certificate proves an award, but recognition needs the qualification's level, learning outcomes and quality assurance — usually confirmed through the register, transcript and diploma supplement." },
    { a: "Academic recognition", b: "Professional recognition", simple: "One is for study; the other is for work.", pro: "Academic recognition concerns access to further study; professional recognition concerns the right to practise, often in a regulated profession with additional legal conditions.", diff: [["Purpose", "Further study / admission", "Right to practise"], ["Decision-maker", "University / education authority", "Professional regulator"]], eduEg: "Recognising a bachelor's degree for master's admission.", lmEg: "Recognising a medical degree to practise medicine.", mistake: "Assuming academic recognition automatically grants the right to work.", question: "Does academic recognition let someone practise a regulated profession?", model: "No. Academic recognition addresses study access only. Practising a regulated profession requires professional recognition, which may add licensing or aptitude requirements set by the regulator." },
    { a: "Equivalence", b: "Comparability", simple: "Equivalence says 'the same'; comparability says 'similar'.", pro: "Equivalence claims two qualifications are the same; comparability judges how similar they are on level and learning outcomes. Modern recognition prefers comparability because systems legitimately differ.", diff: [["Claim", "Sameness", "Degree of similarity"], ["Risk", "Overstates precision", "Realistic and defensible"]], eduEg: "Saying two degrees are 'equivalent'.", lmEg: "Stating a foreign degree is 'comparable to level six'.", mistake: "Using 'equivalence' when only comparability can be shown.", question: "Why do recognition authorities avoid the word 'equivalence'?", model: "Because systems differ in structure and duration, exact sameness is rarely provable. Comparability — a judgement of similar level and outcomes — is more honest, more defensible, and consistent with recognition conventions." },
    { a: "Recognition", b: "Validation", simple: "Recognition accepts a qualification; validation confirms learning meets a standard.", pro: "Recognition accepts an existing qualification for a purpose. Validation (in RPL) confirms that prior learning meets defined outcomes. In qualification development, 'validation' also means approving a new qualification.", diff: [["Object", "An awarded qualification", "Prior learning / a new qualification"]], eduEg: "Recognising a foreign diploma.", lmEg: "Validating a technician's workplace learning.", mistake: "Confusing the RPL and development senses of 'validation'.", question: "Is recognition the same as validation of prior learning?", model: "No. Recognition accepts an existing qualification. Validation of prior learning assesses experience against standards to award credit. They serve different applicants and follow different procedures." },
    { a: "Accreditation", b: "Recognition", simple: "Accreditation checks providers; recognition accepts qualifications.", pro: "Accreditation is quality assurance of an institution or programme. Recognition is a decision about a specific qualification held by a person. Accreditation status is one input to a recognition decision.", diff: [["Subject", "Institution / programme", "A person's qualification"]], eduEg: "Accrediting a university.", lmEg: "Recognising a graduate's degree for employment.", mistake: "Refusing recognition solely because accreditation is unfamiliar.", question: "Should recognition be refused if the awarding institution's accreditation is unclear?", model: "Not automatically. Unclear status is a reason to seek evidence — from the register, the authority, or the ENIC-NARIC network — not an automatic refusal. Refusal needs a justified substantial difference." },
    { a: "Learning outcome", b: "Assessment criterion", simple: "The outcome is what is learned; the criterion is how it's judged.", pro: "A learning outcome states what a learner will know or do; an assessment criterion specifies the evidence that shows the outcome has been achieved.", diff: [["Answers", "What is learned", "How achievement is judged"]], eduEg: "Outcome: 'Evaluate QA arrangements.'", lmEg: "Criterion: 'Identifies two improvements with evidence.'", mistake: "Writing criteria as vague as the outcome.", question: "Why must every learning outcome have an assessment criterion?", model: "Because an outcome that cannot be judged cannot be assessed fairly. Criteria make outcomes measurable, support reliability between assessors, and ensure the assessment truly measures the intended learning." },
    { a: "Occupational standard", b: "Qualification standard", simple: "One describes the job; the other describes the award.", pro: "An occupational standard defines the competences an occupation requires. A qualification standard translates those into learning outcomes, level and assessment for an award.", diff: [["Describes", "The occupation", "The qualification"]], eduEg: "Qualification standard for a level-four IT diploma.", lmEg: "Occupational standard for a network technician.", mistake: "Designing a qualification without an occupational standard.", question: "Why start qualification design from an occupational standard?", model: "Because it anchors the qualification in real labour-market needs. Without it, qualifications risk certifying learning that employers do not value, weakening relevance and graduate employability." },
    { a: "Qualification level", b: "Education level", simple: "Framework level ≠ years of schooling.", pro: "A qualification level reflects the complexity of learning outcomes on the framework; an education level often refers to a stage (primary, secondary, tertiary). The two do not map one-to-one.", diff: [["Basis", "Learning outcomes / complexity", "Educational stage / duration"]], eduEg: "A short but demanding qualification at level six.", lmEg: "A long programme that is nonetheless level four.", mistake: "Inferring level from duration or stage.", question: "Why can a shorter programme be at a higher level than a longer one?", model: "Because level reflects the complexity and autonomy of the learning, not time spent. A concentrated programme with advanced outcomes can sit above a longer programme with more basic outcomes." },
    { a: "Full recognition", b: "Partial recognition", simple: "Full accepts everything; partial accepts part.", pro: "Full recognition accepts the qualification for the intended purpose. Partial recognition accepts comparable components while identifying gaps, often with credit or conditions.", diff: [["Scope", "Whole qualification / purpose", "Components or limited purpose"]], eduEg: "Full access to a master's.", lmEg: "Credit for three of five units.", mistake: "Refusing outright where partial recognition would be proportionate.", question: "When is partial recognition the right outcome?", model: "When a real, substantial difference affects part of the qualification but comparable learning is clearly evidenced elsewhere. Partial recognition is the proportionate middle path between full recognition and refusal." },
    { a: "Automatic recognition", b: "Case-by-case recognition", simple: "One is by rule; the other is by individual assessment.", pro: "Automatic recognition applies a general rule or agreement without individual assessment. Case-by-case recognition assesses each qualification individually against the host system.", diff: [["Process", "Rule / agreement", "Individual assessment"]], eduEg: "Automatic recognition under a regional agreement.", lmEg: "Individual evaluation of an unfamiliar degree.", mistake: "Expecting automatic recognition without an underpinning agreement.", question: "What makes automatic recognition possible?", model: "Mutual trust between quality-assured systems, usually formalised in an agreement. Where that trust and agreement are absent, case-by-case assessment remains necessary." },
    { a: "Regulated profession", b: "Non-regulated profession", simple: "One is legally restricted; the other is not.", pro: "A regulated profession legally restricts practice to holders of specific qualifications; in a non-regulated profession, the employer decides on suitability.", diff: [["Access", "Legally restricted", "Employer's decision"]], eduEg: "Medicine (regulated).", lmEg: "Many IT roles (non-regulated).", mistake: "Applying regulatory conditions to a non-regulated role.", question: "Why does recognition differ for regulated professions?", model: "Because access is set by law to protect the public. For non-regulated roles, recognition informs the employer, who makes the hiring decision; for regulated ones, the regulator's conditions govern practice." },
    { a: "Formal learning", b: "Non-formal / informal learning", simple: "Formal is in the system; the others are outside it.", pro: "Formal learning is structured within the education system and certified. Non-formal learning is structured but outside it; informal learning is unstructured, from daily life and work.", diff: [["Structure", "Structured + certified", "Non-formal: structured, uncertified / Informal: unstructured"]], eduEg: "A university course (formal).", lmEg: "On-the-job training (non-formal); learning by doing (informal).", mistake: "Ignoring non-formal and informal learning in RPL.", question: "Why should recognition consider non-formal and informal learning?", model: "Because much valuable competence is gained outside formal education. Recognising it through RPL widens access, values experience, and reflects how adults actually learn." },
    { a: "Micro-credential", b: "Full qualification", simple: "Micro is small and focused; a qualification is larger.", pro: "A micro-credential certifies a specific, small volume of learning; a full qualification certifies a broad, structured programme at a level. Micro-credentials may stack towards qualifications.", diff: [["Size", "Small, focused", "Broad, structured"], ["Stackability", "Often stackable", "Usually complete"]], eduEg: "A micro-credential in data ethics.", lmEg: "A full diploma in data science.", mistake: "Treating any short course as equivalent to a qualification.", question: "Can micro-credentials form part of a full qualification?", model: "Yes, when they are quality-assured, credit-bearing and stackable. Clear metadata, defined outcomes and assessment allow accumulation towards a full qualification without lowering standards." },
    { a: "Credit transfer", b: "Qualification recognition", simple: "One moves credit; the other accepts a whole qualification.", pro: "Credit transfer recognises specific credit towards a programme; qualification recognition accepts a complete qualification for study or work.", diff: [["Object", "Units of credit", "A whole qualification"]], eduEg: "Transferring 30 credits between programmes.", lmEg: "Recognising a full foreign degree.", mistake: "Confusing partial credit with full recognition.", question: "How does credit transfer differ from recognising a qualification?", model: "Credit transfer moves specific learning into a programme the learner is pursuing. Recognition accepts an already-completed qualification for a purpose. The first builds towards an award; the second accepts one." }
  ];

  /* ---- Qualification development chain (Section 9) ---- */
  var DEV_CHAIN = [
    { stage: "Labour-market intelligence", org: "Sector councils / labour authorities", input: "Employer data, skills forecasts", output: "Identified skills needs", term: ["labour-market relevance", "skills gap"], phrase: "The evidence points to an emerging skills gap in...", risk: "Weak or outdated data leads to irrelevant qualifications." },
    { stage: "National qualifications framework", org: "Qualifications authority", input: "Skills needs, level descriptors", output: "Level placement rules", term: ["level descriptor", "referencing"], phrase: "The qualification will be placed at level six of the framework.", risk: "Inconsistent level placement undermines trust." },
    { stage: "Sectoral qualifications framework", org: "Sector council", input: "Sector needs, NQF descriptors", output: "Sector pathways", term: ["sectoral qualifications framework", "occupational group"], phrase: "Within the sector, this sits on the technician pathway.", risk: "Sector frameworks drifting from the national one." },
    { stage: "Occupational standard", org: "Employers + sector body", input: "Occupational profile", output: "Competence requirements", term: ["occupational standard", "competence requirement"], phrase: "The occupational standard was validated with employers.", risk: "Standards written without genuine employer input." },
    { stage: "Qualification standard", org: "Awarding body / authority", input: "Occupational standard", output: "Learning outcomes, level, assessment", term: ["qualification standard", "learning outcome"], phrase: "The qualification standard translates the job into outcomes.", risk: "Outcomes not matching the occupational standard." },
    { stage: "Curriculum design", org: "Training providers", input: "Qualification standard", output: "Programme and materials", term: ["constructive alignment", "curriculum design"], phrase: "The curriculum is aligned to the intended outcomes.", risk: "Teaching drifting from the standard." },
    { stage: "Training delivery", org: "Training providers", input: "Curriculum", output: "Learning experiences", term: ["faculty development", "delivery"], phrase: "Delivery must prepare learners for authentic assessment.", risk: "Delivery quality varying across providers." },
    { stage: "Assessment", org: "Assessment body / assessors", input: "Assessment strategy", output: "Assessment decisions", term: ["assessment strategy", "moderation"], phrase: "Assessment is competence-based and moderated.", risk: "Inconsistent or unreliable assessment." },
    { stage: "Certification", org: "Awarding body", input: "Assessment decisions", output: "Qualification / units awarded", term: ["certification", "qualification award"], phrase: "Certification confirms the outcomes have been met.", risk: "Certificates that don't reflect real competence." },
    { stage: "Labour-market feedback", org: "Employers / tracer studies", input: "Graduate performance", output: "Evidence for review", term: ["graduate tracer study", "review cycle"], phrase: "Feedback feeds the next qualification review cycle.", risk: "No feedback loop, so qualifications go stale." }
  ];

